import re

def is_valid_ipv4_cidr(s):
    match = re.fullmatch(r'([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})/([0-9]{1,2})', s)
    if not match:
        return False
    octets = match.groups()[:4]
    prefix = match.group(5)
    for o in octets:
        if len(o) > 1 and o[0] == '0':
            return False
        if int(o) > 255:
            return False
    if len(prefix) > 1 and prefix[0] == '0':
        return False
    return int(prefix) <= 32

