def digit_sum(n):
    n = abs(n)
    if n < 10:
        return n
    return n % 10 + digit_sum(n // 10)

def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        lengths = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return lengths[m - 1]

    bm, bd = birth_md
    y, m, d = today_ymd
    count = 0
    while (m, d) != (bm, bd):
        d += 1
        if d > days_in_month(y, m):
            d = 1
            m += 1
            if m > 12:
                m = 1
                y += 1
        count += 1
    return count

