def top_n_frequent(items, n):
    from collections import Counter
    counts = Counter(items)
    buckets = {}
    for word, cnt in counts.items():
        buckets.setdefault(cnt, []).append(word)
    result = []
    for cnt in sorted(buckets.keys(), reverse=True):
        for word in sorted(buckets[cnt]):
            result.append((word, cnt))
    return result[:n]

