def add_months(year, month, n):
    y, m = year, month
    if n >= 0:
        for _ in range(n):
            m += 1
            if m > 12:
                m = 1
                y += 1
    else:
        for _ in range(-n):
            m -= 1
            if m < 1:
                m = 12
                y -= 1
    return (y, m)

