def is_emirp(n):
    def is_prime(x):
        if x < 2:
            return False
        return all(x % i != 0 for i in range(2, int(x ** 0.5) + 1))
    rev = int(str(n)[::-1])
    return rev != n and is_prime(n) and is_prime(rev)

def sort_by_remainder(nums, m):
    from collections import defaultdict
    buckets = defaultdict(list)
    for n in nums:
        buckets[n % m].append(n)
    result = []
    for r in range(m):
        if r in buckets:
            result.extend(sorted(buckets[r]))
    return result

